using System; using System.Reflection; class I { static int Main(){var a=Assembly.LoadFrom(@"F:\vam1.22.0.12\VaM_Data\Managed\Assembly-CSharp.dll"); foreach(var tn in new[]{"FileBrowserUI","MeshVR.PresetManagerControl","JSONStorableActionPresetFilePath","JSONStorableUrl"}){var t=a.GetType(tn); Console.WriteLine("TYPE="+tn+" => "+t); if(t==null)continue; foreach(var f in t.GetFields(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static)){var n=f.Name.ToLowerInvariant(); if(n.Contains("file")||n.Contains("format")||n.Contains("extension")||n.Contains("path")||n.Contains("dir")||n.Contains("filter")||n.Contains("package")||n.Contains("browse")||n.Contains("url")||n.Contains("preset"))Console.WriteLine("FIELD "+f.FieldType+" "+f.Name+" public="+f.IsPublic);} foreach(var p in t.GetProperties(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static)){var n=p.Name.ToLowerInvariant(); if(n.Contains("file")||n.Contains("format")||n.Contains("extension")||n.Contains("path")||n.Contains("dir")||n.Contains("filter")||n.Contains("package")||n.Contains("browse")||n.Contains("url")||n.Contains("preset"))Console.WriteLine("PROP "+p.PropertyType+" "+p.Name);} foreach(var m in t.GetMethods(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static)){var n=m.Name.ToLowerInvariant(); if(n.Contains("file")||n.Contains("format")||n.Contains("extension")||n.Contains("path")||n.Contains("dir")||n.Contains("filter")||n.Contains("browse")||n.Contains("show")||n.Contains("loadpreset"))Console.WriteLine((m.IsPublic?"PUBLIC ":"NONPUBLIC ")+m);} } return 0; }}
